// Package corpus replays the committed corpus goldens through the Go engine
// (M1-WP8) — the parity gate: the goldens were generated by the TS reference
// (npm run corpus:accept), so byte-equality here proves TS⇄Go parity for
// parse, canonical print, IR marshal, and validation on every corpus file.
// Converters are TS-only by design; this package replays canonical.pcd.
package corpus

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"testing"

	"github.com/pijalu/panelcraft/internal/ir"
	"github.com/pijalu/panelcraft/internal/pdl"
)

type caseDiags struct {
	Parse    []pdl.Diagnostic `json:"parse"`
	Validate []pdl.Diagnostic `json:"validate"`
}

const root = "../../testdata/corpus"

func corpusDirs(t *testing.T) []string {
	t.Helper()
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Fatalf("read corpus root: %v", err)
	}
	var dirs []string
	for _, e := range entries {
		if e.IsDir() {
			dirs = append(dirs, e.Name())
		}
	}
	sort.Strings(dirs)
	if len(dirs) < 15 {
		t.Fatalf("corpus has %d seeds, want ≥15", len(dirs))
	}
	return dirs
}

func readBytes(t *testing.T, path string) []byte {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return raw
}

func loadDiags(t *testing.T, dir string) caseDiags {
	t.Helper()
	var cd caseDiags
	if err := json.Unmarshal(readBytes(t, filepath.Join(root, dir, "diagnostics.json")), &cd); err != nil {
		t.Fatalf("%s: diagnostics.json: %v", dir, err)
	}
	return cd
}

func assertDiags(t *testing.T, dir, what string, want, got []pdl.Diagnostic) {
	t.Helper()
	if len(want) == len(got) {
		same := true
		for i := range want {
			if want[i] != got[i] {
				same = false
				break
			}
		}
		if same {
			return
		}
	}
	t.Fatalf("%s: %s diagnostics diverge:\n got: %+v\nwant: %+v", dir, what, got, want)
}

// TestCorpusParity replays every corpus case through the Go engine.
func TestCorpusParity(t *testing.T) {
	for _, dir := range corpusDirs(t) {
		t.Run(dir, func(t *testing.T) {
			canonPath := filepath.Join(root, dir, "canonical.pcd")
			cd := loadDiags(t, dir)
			raw, err := os.ReadFile(canonPath)
			if err != nil {
				// Syntax-abort case: no goldens; replay the raw input instead.
				input := readBytes(t, filepath.Join(root, dir, "input.pcd"))
				res := pdl.Parse(string(input))
				if res.Doc != nil {
					t.Fatalf("%s: doc must be nil (syntax abort)", dir)
				}
				assertDiags(t, dir, "parse", cd.Parse, res.Diagnostics)
				return
			}
			res := pdl.Parse(string(raw))
			if res.Doc == nil {
				t.Fatalf("%s: canonical.pcd must parse: %+v", dir, res.Diagnostics)
			}
			assertDiags(t, dir, "canonical parse", cd.Parse, res.Diagnostics)
			assertDiags(t, dir, "validate", cd.Validate, pdl.Validate(res.Doc, pdl.Options{}))
			if got := pdl.PrintDoc(res.Doc); got != string(raw) {
				t.Fatalf("%s: canonical print diverges:\n got: %q\nwant: %q", dir, got, string(raw))
			}
			out, err := ir.Marshal(res.Doc)
			if err != nil {
				t.Fatalf("%s: marshal: %v", dir, err)
			}
			golden := readBytes(t, filepath.Join(root, dir, "canonical.ir.json"))
			if string(out) != string(golden) {
				t.Fatalf("%s: IR JSON diverges (want %d bytes, got %d bytes)", dir, len(golden), len(out))
			}
		})
	}
}
